import { CliExit, getProgramName, parseCliArguments } from './lib/cli_parser.mjs';
import { Money } from './lib/money.mjs';

const programName = getProgramName(process.argv[1] ?? 'test6.mjs');

try {
  const args = parseCliArguments(process.argv.slice(2), programName);
  const money = new Money(args.amount, args.currency);
  const halved = money.divide(2);

  console.log(halved.amount);
} catch (error) {
  if (error instanceof CliExit) {
    const stream = error.stream === 'stdout' ? process.stdout : process.stderr;

    stream.write(error.text);
    process.exit(error.code);
  }

  throw error;
}

