const DECIMAL_FLOAT_PATTERN = /^[+\-]?(?:(?:\d(?:_?\d)*)\.(?:\d(?:_?\d)*)?|(?:\.\d(?:_?\d)*)|(?:\d(?:_?\d)*))(?:[eE][+\-]?\d(?:_?\d)*)?$/;
const SPECIAL_FLOAT_PATTERN = /^[+\-]?(?:inf(?:inity)?|nan)$/i;
const ARGPARSE_NEGATIVE_NUMBER_PATTERN = /^-\d+$|^-\d*\.\d+$/;

function normalizeExponent(exponentialText) {
  const [rawMantissa, rawExponent] = exponentialText.split('e');
  const mantissa = rawMantissa.includes('.')
    ? rawMantissa.replace(/(\.\d*?)0+$/, '$1').replace(/\.$/, '')
    : rawMantissa;
  const exponentSign = rawExponent.startsWith('-') ? '-' : '+';
  const exponentDigits = rawExponent.slice(1).padStart(2, '0');

  return `${mantissa}e${exponentSign}${exponentDigits}`;
}

export function parsePythonFloat(text) {
  const trimmed = String(text).trim();

  if (trimmed === '') {
    return { ok: false };
  }

  if (SPECIAL_FLOAT_PATTERN.test(trimmed)) {
    const lower = trimmed.toLowerCase();

    if (lower === 'inf' || lower === '+inf' || lower === 'infinity' || lower === '+infinity') {
      return { ok: true, value: Infinity };
    }

    if (lower === '-inf' || lower === '-infinity') {
      return { ok: true, value: -Infinity };
    }

    return { ok: true, value: Number.NaN };
  }

  if (!DECIMAL_FLOAT_PATTERN.test(trimmed)) {
    return { ok: false };
  }

  const normalized = trimmed.replace(/_/g, '');
  const value = Number(normalized);

  if (Number.isNaN(value)) {
    return { ok: false };
  }

  return { ok: true, value };
}

export function formatPythonFloat(value) {
  if (Number.isNaN(value)) {
    return 'nan';
  }

  if (value === Infinity) {
    return 'inf';
  }

  if (value === -Infinity) {
    return '-inf';
  }

  if (Object.is(value, -0)) {
    return '-0.0';
  }

  if (Object.is(value, 0)) {
    return '0.0';
  }

  const absoluteValue = Math.abs(value);

  if (absoluteValue >= 1e16 || absoluteValue < 1e-4) {
    return normalizeExponent(value.toExponential());
  }

  const fixedText = value.toString();

  return fixedText.includes('.') ? fixedText : `${fixedText}.0`;
}

export function isArgparseNegativeNumberToken(token) {
  return ARGPARSE_NEGATIVE_NUMBER_PATTERN.test(token);
}

