import { isKnownCurrencyCode, normalizeCurrencyCode } from './currencies.mjs';
import { decimalToString, divideDecimalByTwo, parseDecimalLiteral } from './decimal.mjs';
import { formatPythonFloat } from './python_float.mjs';

export class CurrencyDoesNotExist extends Error {
  constructor(code) {
    super(`No currency with code ${code} is defined.`);
    this.name = 'CurrencyDoesNotExist';
  }
}

export class Money {
  constructor(amount, currency) {
    const normalizedCurrency = normalizeCurrencyCode(currency);

    if (!isKnownCurrencyCode(normalizedCurrency)) {
      throw new CurrencyDoesNotExist(normalizedCurrency);
    }

    this.currency = normalizedCurrency;
    this._decimal = parseDecimalLiteral(formatPythonFloat(amount));
  }

  static fromDecimal(decimal, currency) {
    const instance = Object.create(Money.prototype);

    instance.currency = currency;
    instance._decimal = decimal;

    return instance;
  }

  divide(divisor) {
    if (divisor !== 2) {
      throw new RangeError('Only division by 2 is supported.');
    }

    return Money.fromDecimal(divideDecimalByTwo(this._decimal), this.currency);
  }

  get amount() {
    return decimalToString(this._decimal);
  }
}

